from build_all import V, U, CLASSIC, card

# ── Institutional Theory (re-built from OpenAlex, replaces the Crossref-only pilot) ──
card("institutional-theory", "Institutional Theory",
  V("W3123282572"),
  "Organizations in the same field (universities, hospitals, NGOs, banks) tend to become more alike over time. DiMaggio and Powell argue this is often not because the shared form is the most efficient, but because looking like the others brings legitimacy. They name three pressures that produce this sameness: coercive (rules and demands from the state, donors or parent organizations), mimetic (copying peers that seem successful when the way forward is uncertain) and normative (shared standards spread by professions and education).",
  ["Why do organizations in one sector adopt the same policies, structures or reforms (e.g. quality-assurance units in universities, gender policies in NGOs)?",
   "Why does what an organization says it does (formal policy) differ from what it actually does?",
   "How do donor, state or professional pressures shape organizations in a developing or post-Soviet context?",
   "Typical data: organizational documents and policies, interviews with managers and staff, comparison across several organizations in one field."],
  ["Saying 'isomorphism' without naming which of the three mechanisms is at work, and what evidence shows it.",
   "Assuming that adopting a policy means implementing it. Check for decoupling between formal structure and daily practice.",
   "Using the theory to explain how individuals change institutions without adding a strand built for agency (institutional work or institutional entrepreneurship).",
   "Treating Meyer & Rowan (1977) and DiMaggio & Powell (1983) as the same argument: the first is about myth, ceremony and decoupling, the second about why organizations become alike."],
  [("foundation", V("W1965278510"), "Organizations adopt formal structures as 'myth and ceremony' to look legitimate, and often decouple them from the actual work."),
   ("foundation", V("W2018944729"), "Micro-level view: the more institutionalized a behaviour, the more it is taken for granted and the longer it persists."),
   ("refinement", V("W4233898295"), "Organizations do not just conform: they can acquiesce, compromise, avoid, defy or manipulate institutional pressures."),
   ("refinement", V("W2154820256"), "Brings the 'old' and 'new' institutionalism together to explain radical change inside organizations, not only stability."),
   ("synthesis", U(["Scott, W. Richard"], 1995, "Institutions and Organizations", "Sage", CLASSIC + " Later editions: 2001, 2008, 2014."), "Organizes institutions into three pillars: regulative, normative and cultural-cognitive. Widely used by students as a coding frame.")],
  [("Institutional logics", "Fields hold several competing belief systems (e.g. professional vs market); actors draw on them, and shifts between them change organizations.", V("W2080841932")),
   ("Institutional work", "Looks at the purposeful actions of people and organizations to create, maintain and disrupt institutions.", V("W2185176023")),
   ("Institutional entrepreneurship", "How actors who are themselves shaped by institutions still manage to change them (the 'paradox of embedded agency').", V("W2017685754"))],
  [("Explains why organizations adopt structures and practices that are not the most efficient: legitimacy, not only efficiency, drives adoption.", V("W1965278510")),
   ("Gives a ready vocabulary for the gap between formal policy and real practice (decoupling), common in reform and donor-funded settings.", V("W1965278510")),
   ("A mature, widely used lens for organization- and field-level questions, so there is a large body of studies to compare findings with.", V("W1972612559"))],
  [("The 'new' institutionalism became too structural and lost the old institutionalism's attention to action and interests; the authors argue the two should be reconciled.", V("W1982662992")),
   ("Better at explaining sameness and stability than change. If actors are shaped by institutions, how do they change them? Later work had to add agency explicitly.", V("W2017685754")),
   ("The theory has been stretched far beyond its core purpose: understanding how organizational structures acquire meaning and continuity beyond technical goals.", V("W1972612559"))],
  [("original", V("W3123282572"), None, "The source of the three mechanisms most students cite; short and clearly argued.", "Which of the three mechanisms (coercive, mimetic, normative) do you expect in your organizations, and what evidence in your data would show it?"),
   ("refinement", V("W4233898295"), None, "Shows that organizations respond to pressure in different ways, which helps if your participants resist or game the rules.", "Which of Oliver's five responses would you expect from the organizations in your study, and what would make them choose it?"),
   ("review", V("W1972612559"), None, "A short critical summary of where the theory stands and where it has been overstretched.", "Which of the four research threads Suddaby proposes is closest to your question?")],
  notes="Thornton & Ocasio (1999): the title recalled from memory was wrong; corrected from the record.")

# ── Social constructionism ──
card("social-constructionism", "Social constructionism",
  U(["Berger, Peter L.", "Luckmann, Thomas"], 1966, "The Social Construction of Reality: A Treatise in the Sociology of Knowledge", "Doubleday", CLASSIC + " OpenAlex collects its citations on a 1967 record (W2073506374) that also lists a reviewer as author; used only as the citation anchor for recent works."),
  "What people treat as obvious reality (roles, institutions, what counts as normal or true) is produced by people interacting and is then experienced as objective. Berger and Luckmann describe this as a cycle: people create social order (externalization), it comes to feel like a fact outside them (objectivation), and new generations learn it as simply how things are (internalization).",
  ["How did a category or meaning come to be taken for granted (e.g. 'a good student', 'national dress', 'corruption')?",
   "How do participants talk about, define and negotiate a phenomenon?",
   "Interpretive qualitative designs: interviews, discourse and media analysis, document analysis."],
  ["Reading 'socially constructed' as 'not real' or 'fake'. Constructed things have real consequences.",
   "Not saying what exactly is constructed, by whom and through which practices.",
   "Combining it with a design that measures 'true' values of variables without addressing the clash in research philosophy.",
   "Citing Berger & Luckmann as if they offered a method for discourse analysis. They offer a theory of knowledge, not a method."],
  [("strand", V("W4230958478", "Routledge reissue (2017) of the 1977 book."), "Treats social problems as claims-making activities: a problem exists when groups successfully define it as one."),
   ("refinement", V("W2157525610", "OpenAlex's abstract for this record belongs to a different text; check the title page."), "Brings constructionism into psychology: knowledge is a product of social exchange, not a mirror of the mind or the world."),
   ("synthesis", V("W1785520540"), "The standard introduction that organized constructionist ideas for social-science students.")],
  [("Social problems as claims-making", "Studies how conditions become recognized 'problems' through claims by groups, media and experts.", V("W4230958478", "Routledge reissue (2017) of the 1977 book.")),
   ("Constructionism in psychology", "Treats knowledge, emotion and the self as produced in relationships and language.", V("W2157525610", "OpenAlex's abstract for this record belongs to a different text."))],
  [("Explains how roles and institutions come to feel natural even though people made them, which opens them to questioning.", U(["Berger, Peter L.", "Luckmann, Thomas"], 1966, "The Social Construction of Reality", "Doubleday", CLASSIC)),
   ("Gives qualitative researchers a clear rationale for studying meanings, language and interaction rather than 'objective' variables.", V("W1785520540"))],
  [("Studies often treat some conditions as constructed while quietly treating others as objectively given. The authors call this boundary-drawing 'ontological gerrymandering'.", V("W2169609726")),
   ("'Social construction' is used so loosely that it often says little. Researchers should state what exactly is constructed (an idea, a category, an object) and what follows from that.", V("W4299955896"))],
  [("original", U(["Berger, Peter L.", "Luckmann, Thomas"], 1966, "The Social Construction of Reality", "Doubleday", CLASSIC), "Parts II and III ('Society as Objective Reality', 'Society as Subjective Reality')", "Where the cycle of externalization, objectivation and internalization is set out.", "Which taken-for-granted 'fact' in your topic could you trace back to how people created and passed it on?"),
   ("refinement", V("W2169609726"), None, "Short and sharp; helps you avoid the most common inconsistency in constructionist studies.", "In your study, what are you treating as constructed and what as given, and can you justify the line?"),
   ("review", V("W1785520540"), None, "A clear map of what constructionism claims and how it is used in research.", "Which version of constructionism (strong or moderate) fits how you plan to analyse your data?")],
  anchor="W2073506374")

# ── Structuration theory ──
card("structuration-theory", "Structuration Theory",
  V("W1515810707", "OpenAlex record that collects the book's citations (typed as article)."),
  "Structure and agency make each other. When people act they draw on rules and resources (structure), and by acting they reproduce or change those same rules and resources. Giddens calls this the duality of structure: structure is both the medium and the outcome of action.",
  ["How are routines, rules or practices in an organization reproduced or changed over time?",
   "How does the way people use a technology reshape the organization around it?",
   "Longitudinal qualitative designs: observation, repeated interviews, case studies that follow practices over time."],
  ["Using 'duality of structure' as a label without showing the loop in the data: which rules and resources people drew on, and what their actions reproduced or changed.",
   "Trying to measure 'structure' as a variable. In Giddens's sense structure exists only when people draw on it.",
   "Expecting a ready-made method. Giddens gave few methodological guidelines; you will need to borrow one."],
  [("refinement", V("W3183765052"), "Shows the same technology (CT scanners) leading to different structures in two hospital departments: technology as an occasion for structuring."),
   ("refinement", V("W2101419153"), "The duality of technology: technology is made by human action and also constrains it."),
   ("refinement", V("W2122407370"), "Reformulates structure (via Giddens and Bourdieu) to restore agency and build in the possibility of change.")],
  [("Technology and information systems", "Applies structuration to how technology use shapes and is shaped by organizations.", V("W2101419153")),
   ("Adaptive structuration theory", "Studies how groups appropriate the structures built into technologies such as group decision systems.", V("W2169736278"))],
  [("Widely used and adaptable: a review found 331 information-systems articles (1983–2004) drawing on Giddens.", V("W1601482672")),
   ("One of the main attempts to bridge structure and agency, and a base other theorists build on.", V("W2122407370"))],
  [("Archer contrasts structuration with her morphogenetic approach: by fusing structure and action, structuration makes it hard to study how each changes the other over time.", V("W4250026844")),
   ("The concepts are very abstract and not easily coupled to any method, so the theory is difficult to apply empirically.", V("W2059706776"))],
  [("original", V("W1515810707"), "Chapter 1, 'Elements of the theory of structuration'", "The core concepts in Giddens's own words; the rest of the book can wait.", "Which rules and resources do the people in your study draw on, and what do their actions reproduce?"),
   ("refinement", V("W2101419153"), None, "A model of applying structuration to a concrete object (technology) in organizations.", "What in your study plays the role that technology plays for Orlikowski?"),
   ("review", V("W2059706776"), None, "Practical strategies for doing empirical work with a theory that offers no method.", "Which of the strategies they describe could you use for your data collection and analysis?")])

# ── Postcolonial theory ──
SAID = U(["Said, Edward W."], 1978, "Orientalism", "Pantheon Books", CLASSIC)
card("postcolonial-theory", "Postcolonial theory (research applications)",
  SAID,
  "Colonialism shaped not only economies and borders but also knowledge: how the colonizers described the colonized, which categories became 'normal', and whose voices count as knowledge. Said showed how Western scholarship constructed 'the Orient' as its opposite. Postcolonial research questions such representations and the power behind them.",
  ["How is a region, people or culture represented in media, policy, textbooks or research, and by whom?",
   "How do identity, language and national culture get rebuilt after imperial or Soviet rule?",
   "Whose knowledge counts in a field, and how should research with local communities be done?",
   "Typical data: texts, media, archives, policy documents, interviews; discourse and critical analysis."],
  ["Applying it to Central Asia without addressing whether and how Soviet rule counts as colonial. This is debated; cite the debate.",
   "Treating 'the West' or 'the colonized' as uniform blocks.",
   "Speaking for participants while claiming to give them voice.",
   "Mixing postcolonial (South Asian, Middle Eastern roots) and decolonial (Latin American) thought without saying which one you use."],
  [("refinement", V("W1987351853"), "Shows how Western feminist scholarship produced a single 'Third World woman' through its own categories."),
   ("refinement", V("W1485995441", "2012 Routledge edition of the 1994 book."), "Hybridity, mimicry and the 'third space': colonial identities are mixed and unstable, not simple opposites."),
   ("refinement", V("W2946055890", "2008 edition of the 2000 book."), "European categories of thought are indispensable for studying the non-West and also inadequate for it."),
   ("refinement", V("W2090276112"), "Brings the post-Soviet sphere, including Central Asia, into postcolonial critique.")],
  [("Decolonial thought / coloniality of power", "Latin American strand: colonial hierarchies of race and knowledge outlived formal colonialism.", V("W1536538149", "2008 reprint of the 2000 article.")),
   ("Post-Soviet postcolonial studies", "Asks whether and how Russian and Soviet rule over Central Asia, the Caucasus and Eastern Europe was colonial.", V("W2090276112")),
   ("Indigenous / decolonizing methodologies", "Research itself as part of colonial practice, and how to do it differently with communities.", V("W4251392789", "2021 third edition of the 1999 book."))],
  [("Makes visible how research categories and representations carry power, including in well-meaning scholarship.", V("W1987351853")),
   ("Opens questions about the post-Soviet sphere that the rest of postcolonial studies has largely ignored.", V("W2090276112"))],
  [("Postcolonial criticism pays too little attention to global capitalism as the context of the postcolonial condition.", V("W4289254140")),
   ("The term risks homogenizing very different colonial experiences; its potential and its limits differ in the Middle East and Central Asia.", V("W1951712093"))],
  [("original", SAID, "Introduction", "The founding argument in about thirty pages.", "Who represents your topic or group, and what categories do they use?"),
   ("refinement", V("W2090276112"), None, "The key text for applying postcolonial ideas to the post-Soviet space.", "Does Moore's argument fit the country or group you study? Where does it not?"),
   ("review", V("W1951712093"), None, "A careful comparison of what the postcolonial lens can and cannot do in Central Asia.", "Which of Kandiyoti's limitations matters most for your case, and how will you handle it?")],
  notes="Spivak (1988) and Said (1978) have no clean records; Said is flagged.")

# ── Social capital ──
card("social-capital-theory", "Social capital theory",
  V("W380575115", "2002 reprint of the 1986 chapter."),
  "Relationships are a resource. For Bourdieu, social capital is the resources a person can draw on through membership in a durable network; it can be converted into economic and cultural capital and helps reproduce class inequality. Coleman and Putnam later framed it as the trust, norms and networks that make cooperation and collective action easier.",
  ["How do networks, trust or connections shape access to jobs, credit, education or power?",
   "Why do some communities or organizations cooperate better than others?",
   "Typical data: interviews on networks and help-seeking, network surveys, community case studies."],
  ["Mixing Bourdieu (inequality, individuals and classes) with Putnam (communities, civic life) without saying which version you use.",
   "Assuming more social capital is always good.",
   "Measuring it with one proxy (e.g. number of memberships) and calling that social capital."],
  [("refinement", V("W3123534837"), "Social capital as a resource in social structure that enables action, e.g. family and community ties supporting children's education."),
   ("refinement", V("W2135409175"), "Civic version: networks of civic engagement and trust explain why regional governments in Italy perform differently."),
   ("refinement", V("W2108183214"), "Three dimensions in organizations: structural, relational and cognitive."),
   ("synthesis", V("W2129658695"), "A common framework across disciplines: sources, benefits, risks and contingencies of social capital.")],
  [("Network / structural", "Position in a network matters: weak ties and bridging positions bring new information and opportunities.", V("W2109469951")),
   ("Civic / communitarian", "Social capital as a property of communities: associations, trust, norms of reciprocity.", V("W2135409175")),
   ("Development", "Social capital in development policy: ties within communities and links beyond them.", V("W1533558196"))],
  [("One concept that connects sociology, political science, economics and organization studies.", V("W2129658695")),
   ("Explains how connections give access to information and opportunities that formal qualifications alone do not.", V("W2109469951"))],
  [("Social capital has a downside: strong ties can exclude outsiders, make excessive claims on members, restrict freedom and pull members down to group norms. The concept is also stretched too far.", V("W2115059495")),
   ("Treating social relations as 'capital' imports economic thinking into social science and simplifies what it claims to measure.", V("W1647165795"))],
  [("original", V("W380575115", "2002 reprint of the 1986 chapter."), None, "Short; sets out social capital next to economic and cultural capital.", "In your setting, what can social capital be converted into, and who can't make that conversion?"),
   ("refinement", V("W3123534837"), None, "The other foundational version; compare it with Bourdieu's.", "Is your study closer to Coleman's view (a resource for action) or Bourdieu's (a source of inequality)?"),
   ("review", V("W2115059495"), None, "The classic critical review: origins, uses and downsides.", "Which of the four negative consequences could appear in your data?")])

# ── Practice theory ──
card("practice-theory", "Practice theory",
  V("W4301056702"),
  "Social life is made of practices: routinized ways of doing and saying that combine bodies, objects, know-how and shared meanings. Instead of explaining behaviour by what is in individual minds or by abstract structures, practice theory studies what people actually do, again and again, and how that reproduces or changes social order. Bourdieu's version adds habitus (embodied dispositions) and fields (arenas of struggle).",
  ["How is an everyday practice (teaching, farming, cooking, commuting, consuming) carried out, learned and changed?",
   "Why do routines persist even when people say they want to change them?",
   "How is work in an organization actually done, as opposed to how it is described?",
   "Typical data: observation, ethnography, interviews about doing, diaries, video."],
  ["Studying only what people say about a practice, not the doing itself.",
   "Treating 'practice' as a synonym for 'behaviour' or 'activity' without its elements (materials, competences, meanings).",
   "Using Bourdieu and Schatzki interchangeably; they are different versions."],
  [("refinement", V("W2097379326"), "Identifies 'practice' as the emerging key orientation in anthropological theory."),
   ("refinement", V("W2120969145"), "Defines practice theory as an alternative to explaining the social through minds, texts or interaction."),
   ("refinement", V("W86961873"), "A simple model: practices are made of materials, competences and meanings, and change when links between them change.")],
  [("Bourdieusian", "Habitus, capital and field: practices reproduce social position.", V("W4301056702")),
   ("Consumption and sustainability", "Everyday consumption understood through the practices it serves.", V("W2119020812")),
   ("Organizations", "Practice as an empirical focus, a theory and a philosophy in organization studies.", V("W2151363056"))],
  [("Offers an alternative to explaining social life through individual minds or texts alone.", V("W2120969145")),
   ("Works well for everyday routines such as consumption, where individual-choice explanations fall short.", V("W2119020812"))],
  [("Bourdieu's scheme remains deterministic and circular: structures produce dispositions, which produce practices, which reproduce the structures.", V("W1996724386")),
   ("The habitus concept retreats into objectivism and conflicts with Bourdieu's own emphasis on practical interaction.", V("W2159337037"))],
  [("original", V("W4301056702"), "Chapter 2, 'Structures and the habitus'", "Where habitus is defined.", "Which dispositions do the people in your study bring to the practice, and where did they learn them?"),
   ("refinement", V("W2120969145"), None, "The clearest short definition of practice theory.", "What exactly is the 'practice' in your study, and what are its elements?"),
   ("review", V("W2151363056"), None, "How practice theory is used in organization research, with three ways to use it.", "Are you using practice as an empirical focus, a theory, or a philosophy?")],
  notes="Schatzki (1996) has no clean record and is left out of this card until checked.")

# ── Diffusion of Innovations ──
ROG = U(["Rogers, Everett M."], 1962, "Diffusion of Innovations", "Free Press", CLASSIC + " Fifth edition 2003. OpenAlex collects citations on W1990513740 (a 2019 chapter by Rogers, Singhal & Quinlan); used only as the citation anchor.")
card("diffusion-of-innovations", "Diffusion of Innovations",
  ROG,
  "New ideas, practices and technologies spread through a social system over time via communication channels. Whether people adopt depends on how they perceive the innovation (relative advantage, compatibility, complexity, trialability, observability). Adopters range from innovators and early adopters to the late majority and laggards, which produces the familiar S-shaped adoption curve.",
  ["Why are some practices, technologies or policies adopted faster than others in a community or organization?",
   "Who adopts first, and through which channels does an innovation spread?",
   "Typical data: surveys on perceived attributes and adoption, interviews with adopters and non-adopters, adoption records over time."],
  ["Assuming the innovation is good and non-adopters are 'resistant' (pro-innovation bias).",
   "Studying only adopters, not rejecters or people who stopped using the innovation.",
   "Treating adopter categories as personality types rather than positions in time.",
   "Ignoring organizational and system context when studying adoption in organizations."],
  [("refinement", V("W4253543067"), "A mathematical model of how adoption grows over time, driven by innovators and imitators."),
   ("strand", V("W1791587663"), "Focuses on individual acceptance of technology through perceived usefulness and ease of use."),
   ("synthesis", V("W2081753990"), "A systematic review that builds an evidence-based model of diffusion in service organizations.")],
  [("Technology acceptance", "Individual-level models of technology adoption (TAM, UTAUT).", V("W1791587663")),
   ("Organizational diffusion", "How innovations spread and are sustained in organizations and health services.", V("W2081753990"))],
  [("Draws on a very large, cross-disciplinary body of research, synthesized into usable models.", V("W2081753990")),
   ("Offers concrete constructs that can be turned into survey items.", V("W1791587663"))],
  [("The literature carries a pro-innovation bias, so it struggles to explain why inefficient innovations spread and efficient ones are rejected.", V("W2091775201")),
   ("The theory fits poorly with complex, networked technologies adopted by organizations rather than individuals.", V("W1517087321"))],
  [("original", ROG, "Fifth edition (2003), the chapter on attributes of innovations", "Defines the five perceived attributes most studies measure.", "Which of the five attributes is most likely to explain adoption in your setting, and how would you observe it?"),
   ("refinement", V("W2091775201"), None, "The key correction to the theory's built-in optimism.", "Could the innovation you study be spreading for reasons other than its benefits?"),
   ("review", V("W2081753990"), None, "A rigorous review with a model you can borrow for organizations.", "Which part of the model (innovation, adopters, system, context) is your study about?")],
  anchor="W1990513740")

